package Tv3.Controller;
import Tv3.View.LopHocPage;
import MainPage.View.Workspace;import MainPage.Controller.PageTasks;import Model.*;import Service.*;
import java.util.*;import java.time.*;import java.math.BigDecimal;import javax.swing.*;
public class LopHocController {
 private final LopHocPage v;private final int b;private final LopHocService svc=new LopHocService();private List<LopHocModel> classes=List.of();private List<DanhMucModel> catalog=List.of();private List<NhanSuModel> staff=List.of();private List<DangKyHocModel> regs=List.of();
 private record Data(List<LopHocModel> l,List<DanhMucModel> c,List<NhanSuModel> s,List<DangKyHocModel> r){}
 public LopHocController(LopHocPage v,int b){this(v,b,"Cơ sở #"+b);}
 public LopHocController(LopHocPage v,int b,String name){this.v=v;this.b=b;v.title("QUẢN LÝ LỚP — "+name,"Xếp giáo viên · Sĩ số · Học viên");v.columns("Mã","Tên lớp","Khóa học","Giáo viên","Sĩ số","Bắt đầu","Kết thúc","Học phí","Trạng thái");v.action("+ Thêm lớp",()->edit(null));v.action("Sửa",()->{var x=selected();if(x!=null)edit(x);});v.action("Xóa lớp",()->{var x=selected();if(x!=null)delete(v,b,x.getMaLop(),()->load(false));});v.action("Chi tiết",()->{var x=selected();if(x!=null)openDetails(v,b,x.getMaLop());});v.action("Tải lại",()->load(true));Workspace.popup(v.table,new String[]{"Xem thông tin","Sửa lớp","Xóa lớp"},i->{var x=selected();if(x==null)return;if(i==0)openDetails(v,b,x.getMaLop());else if(i==1)edit(x);else delete(v,b,x.getMaLop(),()->load(false));});load(false);}
 private void load(boolean refresh){v.status("Đang tải...");PageTasks.run(v,()->new Data(refresh?svc.reload(b):svc.selectAll(b),refresh?new DanhMucService().reload(b):new DanhMucService().selectAll(b),refresh?new NhanSuService().reload(b):new NhanSuService().selectAll(b),refresh?new DangKyHocService().reload(b):new DangKyHocService().selectAll(b)),d->{classes=d.l;catalog=d.c;staff=d.s;regs=d.r;v.rows(classes.stream().map(x->new Object[]{x.getMaLop(),x.getTenLop(),cat(x.getMaKhoaHoc()),staff.stream().filter(n->Objects.equals(n.getMaNhanSu(),x.getMaGiaoVien())).map(NhanSuModel::getHoTen).findFirst().orElse(""),regs.stream().filter(r->Objects.equals(r.getMaLop(),x.getMaLop())&&"DANG_HOC".equals(r.getTrangThai())).map(DangKyHocModel::getMaHocVien).distinct().count()+" / "+PageTasks.text(x.getSiSoToiDa()),x.getNgayBatDau(),x.getNgayKetThuc(),x.getHocPhiMacDinh(),x.getTrangThai()}).toArray(Object[][]::new));v.status("Tổng: "+classes.size()+" lớp");});}
 private String cat(Integer id){return catalog.stream().filter(x->Objects.equals(x.getMaDanhMuc(),id)).map(DanhMucModel::getTenDanhMuc).findFirst().orElse("");}
 private LopHocModel selected(){int r=v.selected();if(r<0){Workspace.message(v,"Chọn lớp trước");return null;}int id=(int)v.value(r,0);return classes.stream().filter(x->x.getMaLop()==id).findFirst().orElse(null);}
 public static void openAdd(java.awt.Component owner,int b,Runnable done){PageTasks.run(owner,()->new Data(List.of(),new DanhMucService().selectAll(b),new NhanSuService().selectAll(b),List.of()),d->editForm(owner,b,null,d.c,d.s,done));}
 private void edit(LopHocModel x){editForm(v,b,x,catalog,staff,()->load(false));}
 public static void editForm(java.awt.Component owner,int b,LopHocModel x,List<DanhMucModel> cats,List<NhanSuModel> staff,Runnable done){try{
  var courses=new ArrayList<Workspace.Choice>();courses.add(new Workspace.Choice(0,"Không chọn"));cats.stream().filter(c->"KHOA_HOC".equals(c.getNhomDanhMuc())&&(c.isTrangThai()||x!=null&&Objects.equals(x.getMaKhoaHoc(),c.getMaDanhMuc()))).forEach(c->courses.add(new Workspace.Choice(c.getMaDanhMuc(),c.getTenDanhMuc())));
  var teachers=new ArrayList<Workspace.Choice>();teachers.add(new Workspace.Choice(0,"Chưa xếp"));staff.stream().filter(n->"GIAO_VIEN".equals(n.getVaiTro())&&(n.isTrangThai()||x!=null&&Objects.equals(x.getMaGiaoVien(),n.getMaNhanSu()))).forEach(n->teachers.add(new Workspace.Choice(n.getMaNhanSu(),n.getHoTen())));
  var years=new ArrayList<Workspace.Choice>();years.add(new Workspace.Choice(0,"Không chọn"));cats.stream().filter(c->"NAM_HOC".equals(c.getNhomDanhMuc())).forEach(c->years.add(new Workspace.Choice(c.getMaDanhMuc(),c.getTenDanhMuc())));
  var statusOptions=List.of(new Workspace.Choice(1,"DANG_MO"),new Workspace.Choice(2,"TAM_DUNG"),new Workspace.Choice(3,"DA_DONG"));int statusId=x==null?1:"TAM_DUNG".equals(x.getTrangThai())?2:"DA_DONG".equals(x.getTrangThai())?3:1;
  var f=new Workspace.Form(Workspace.Field.text("Mã hiển thị",x==null?"":x.getMaLopHienThi()),Workspace.Field.text("Tên lớp",x==null?"":x.getTenLop()),Workspace.Field.choice("Khóa học",courses,x==null?0:x.getMaKhoaHoc()),Workspace.Field.choice("Năm học",years,x==null?0:x.getMaNamHoc()),Workspace.Field.choice("Giáo viên",teachers,x==null?0:x.getMaGiaoVien()),Workspace.Field.text("Sĩ số tối đa",x==null?"15":PageTasks.text(x.getSiSoToiDa())),Workspace.Field.text("Bắt đầu (yyyy-MM-dd)",x==null?LocalDate.now().toString():PageTasks.text(x.getNgayBatDau())),Workspace.Field.text("Kết thúc",x==null?"":PageTasks.text(x.getNgayKetThuc())),Workspace.Field.text("Học phí",x==null?"0":PageTasks.text(x.getHocPhiMacDinh())),Workspace.Field.text("Tiền ăn",x==null?"0":PageTasks.text(x.getTienAnMacDinh())),Workspace.Field.choice("Trạng thái",statusOptions,statusId),Workspace.Field.text("Ghi chú",x==null?"":PageTasks.text(x.getGhiChu())));
  f.onChoice(2,()->cats.stream().filter(c->c.getMaDanhMuc()==f.choice(2)).findFirst().ifPresent(c->{String fee=PageTasks.field(c.getCauHinh(),"HocPhiMacDinh");if(!fee.isEmpty())f.text(8,fee);}));if(f.show(owner,"Thông tin lớp","Lưu","Hủy")!=0)return;
  LopHocModel m=x==null?new LopHocModel():x;m.setMaLopHienThi(f.text(0).trim());m.setTenLop(f.text(1).trim());m.setMaKhoaHoc(nullable(f.choice(2)));m.setMaNamHoc(nullable(f.choice(3)));m.setMaGiaoVien(nullable(f.choice(4)));m.setSiSoToiDa(f.text(5).isBlank()?null:Integer.valueOf(f.text(5)));m.setNgayBatDau(LocalDate.parse(f.text(6).trim()));m.setNgayKetThuc(f.text(7).isBlank()?null:LocalDate.parse(f.text(7).trim()));m.setHocPhiMacDinh(new BigDecimal(f.text(8)));m.setTienAnMacDinh(new BigDecimal(f.text(9)));m.setTrangThai(statusOptions.get(f.choice(10)-1).label());m.setGhiChu(f.text(11));PageTasks.run(owner,()->{var s=new LopHocService();PageTasks.require(x==null?s.insert(b,m):s.update(b,m),"Không lưu được lớp");return true;},r->done.run());
 }catch(Exception e){Workspace.message(owner,"WARNING — "+e.getMessage());}}
 private static Integer nullable(int i){return i==0?null:i;}
 public static void delete(java.awt.Component owner,int b,int id,Runnable done){if(!Workspace.confirm(owner,"Xóa lớp #"+id+"? Nếu có dữ liệu liên quan, SQL Server sẽ từ chối."))return;PageTasks.run(owner,()->{PageTasks.require(new LopHocService().delete(b,id),"Không xóa được lớp; kiểm tra dữ liệu liên quan");return true;},r->done.run());}
 public static void openDetails(java.awt.Component owner,int b,int id){LopChiTietPageBridge.open(owner,b,id);}
}
